// 18.11 route 3: an analysis of the measurement history goes to Hermes (read-only HA/InfluxDB, local model).
// The panel's delegate creates the mission with the panel session; the result comes back here once.
async function hermesHandoff(question,{space,archive}){
 const d=globalThis.JarvisHermesDelegate,box=message('JARVIS','Hermes : envoi de la demande…'),line=box.lastChild,say=t=>{line.textContent=t};
 if(!d){say('Hermes : panneau des missions indisponible. Recharge la page, connecte-toi au panneau Missions et repose la question.');return}
 const key=archive&&/^[A-Za-z0-9_-]{1,80}$/.test(String(archive.id))&&Number.isInteger(archive.turn)?'jarvis-route-'+archive.id+'-'+archive.turn:undefined;
 let m;try{m=await d.submit(question,{key})}catch(e){say('Hermes n’a pas pu prendre la demande : '+e.message+'.');return}
 const id=m.id.slice(0,8),labels={queued:'en attente du GPU',running:'analyse en cours',completed:'terminée',failed:'échec',cancelled:'annulée',unknown:'état incertain, à vérifier dans le panneau'};
 say('Hermes : mission '+id+' enregistrée · en attente du GPU. Je te donne le résultat ici.');
 let r;try{r=await d.wait(m.id,m.space,{progress:s=>say('Hermes : mission '+id+' · '+(labels[s]||s)+'.')})}catch(e){say('Hermes : suivi interrompu ('+e.message+'). La mission '+id+' continue : résultat dans le panneau Missions.');return}
 if(space!==currentSpace)return;
 const ok=r.state==='completed'&&r.output;
 const text=ok?'**Résultat de Hermes** (mission '+id+(r.measurements?', '+r.measurements+' lecture'+(r.measurements>1?'s':'')+' réelle'+(r.measurements>1?'s':''):'')+' ; raisonnement du modèle local, à vérifier) :\n\n'+r.output
  :'La mission Hermes '+id+' '+({failed:'a échoué',cancelled:'a été annulée',unknown:'est à vérifier',timeout:'est toujours en cours'}[r.state]||'s’est terminée sans réponse')+'.'+(r.reasons.length?' '+r.reasons.join(' '):'')+' Détails dans le panneau Missions.';
 say('Hermes : mission '+id+' · '+(labels[r.state]||r.state)+'.');message('JARVIS',text);remember('assistant',text);
 const plain=r.output.split('\n').filter(l=>!/^\s*\|/.test(l)).join(' ').replace(/[`*_#>]|\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/\b(?:ha|influx|mission):\/\/\S+/g,'').replace(/\s+/g,' ').trim();
 document.dispatchEvent(new CustomEvent('jarvis:hermes-result',{detail:{speech:ok?'L’analyse de Hermes est prête. '+plain.slice(0,700):text.replace(/\*\*/g,'')}}));
}
